[package]
# Published as `blit-transfer` (D-2026-08-18-1): the crates.io names
# `blit` and `blit-cli` belong to unrelated projects, and cargo
# installs by BINARY name, so `cargo install blit-transfer` still
# yields the `blit` command. The directory stays crates/blit-cli.
name = "blit-transfer"
version.workspace = true
edition = "2021"
license.workspace = true
description = "blit: a fast file transfer tool — local and remote sync, migration, and backup (CLI)"
repository = "https://github.com/roethlar/Blit"
readme = "../../README.md"
keywords = ["file-transfer", "sync", "backup", "mirror", "rsync"]
categories = ["command-line-utilities", "filesystem"]

# The shipped command is named `blit`, matching every doc, manpage,
# and README example; the binary is named via `[[bin]]`. Tests,
# scripts, and CI walk the build dir and look for `blit` / `blit.exe`.
[[bin]]
name = "blit"
path = "src/main.rs"

[dependencies]
tokio = { version = "1", features = ["full"] }
clap = { version = "4", features = ["derive"] }
clap_complete = "4"
blit-core = { path = "../blit-core", version = "0.1.3" }
eyre = "0.6"
color-eyre = "0.6"
log = "0.4"
chrono = { version = "0.4", default-features = false, features = ["clock"] }
indicatif = "0.18"
# clp-3: colour for the live row and failure block. Already in the tree as
# an indicatif dependency; named directly so the styling goes through
# console's capability detection rather than hand-written escapes.
console = "0.16"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"

[dev-dependencies]
# test-util: paused-clock tests for the live progress row's tick arm.
tokio = { version = "1", features = ["full", "test-util"] }
tempfile = "3"
serde = { version = "1.0", features = ["derive"] }
toml = "1.1"
wait-timeout = "0.2"
filetime = "0.2"
tokio-stream = { version = "0.1", features = ["net"] }
tonic = "0.14"
walkdir = "2.5"

[lints]
workspace = true
recovery=available: ptk_output handle=ptko_kCYc4ipQXz2Bzr8VSYsHK9ZPn1pbpiGR_IUTaZmQFR0

