/// The transfer verbs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Verb {
    Copy,
    Mirror,
    Move,
}

impl Verb {
    fn word(self) -> &'static str {
        match self {
            Verb::Copy => "copy",
            Verb::Mirror => "mirror",
            Verb::Move => "move",
        }
    }

    fn from_word(word: &str) -> Option<Self> {
        [Verb::Copy, Verb::Mirror, Verb::Move]
            .into_iter()
            .find(|verb| verb.word() == word)
    }
}

